const results = [];

for (const item of $input.all()) {
  const data = item.json ?? {};

  const execution = data.execution ?? {};
  const workflow = data.workflow ?? {};
  const trigger = data.trigger ?? {};

  const error =
    execution.error ??
    trigger.error ??
    data.error ??
    {};

  const node =
    execution.lastNodeExecuted ??
    error.node?.name ??
    null;

  const message =
    typeof error === "string"
      ? error
      : error.message ??
        data.message ??
        "Kesalahan workflow tidak diketahui";

  results.push({
    json: {
      workflow_name: workflow.name ?? "Unknown Workflow",
      workflow_id: workflow.id
        ? String(workflow.id)
        : null,
      execution_id: execution.id
        ? String(execution.id)
        : null,
      node_name: node,
      error_message: String(message),
      error_stack: error.stack
        ? String(error.stack)
        : null,
      source_url: null,
      status: "open"
    }
  });
}

return results;
